def fcheck(locs):
    if locs.startswith("none"):
        return ""
    out = []
    for rel in locs.split(";"):
        paths = sorted(glob.glob(os.path.join(CF, rel)))
        if not paths:
            raise SystemExit(f"missing local file: {rel}")
        if len(paths) > 3:
            tot = sum(os.path.getsize(p) for p in paths)
            h = hashlib.sha256("".join(hashlib.sha256(open(p, "rb").read()).hexdigest() for p in paths).encode()).hexdigest()[:16]
            out.append(f"{rel}: {len(paths)} files, {tot} bytes, combined sha256 {h}")
        else:
            for p in paths:
                out.append(f"{os.path.relpath(p, CF)}: {os.path.getsize(p)} bytes, sha256 {hashlib.sha256(open(p, 'rb').read()).hexdigest()[:16]}")
    return " | ".join(out)


rows = [dict(source=s, publisher=p, url=u, local_file=l, coverage=c, used_for=f, kind=k, accessed=ACC, file_check=fcheck(l)) for s, p, u, l, c, f, k in S]
df = pd.DataFrame(rows)
assert "\u2014" not in " ".join(df.astype(str).values.ravel())
df.to_csv(os.path.join(CF, "health2_manifest.csv"), index=False)
print(len(df), "sources")
